export { chainFocus, isValidUrl } from "./commands";
export { extensionPresent, nodeActive } from "./detection";
export { shallowEqual, useEditorState } from "./editor-state";
export { DEFAULT_EXTENSION_LABELS } from "./labels";
export type { ExtensionLabelKey, ExtensionLabels } from "./labels";
export { ToolbarProvider, useToolbar, useToolbarEditor } from "./context";
export type { ToolbarContextValue, ToolbarProviderProps } from "./context";
export type { ToolbarComponentProps } from "./types";

import type { ChainedCommands, Editor } from "@tiptap/core";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean =>
  /^https?:\/\/\S+$/.test(url);

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ExtensionLabels } from "./labels";
import { DEFAULT_EXTENSION_LABELS } from "./labels";

export interface ToolbarContextValue {
  editor: Editor | null;
  labels: ExtensionLabels;
}

const ToolbarContext = createContext<ToolbarContextValue>({
  editor: null,
  labels: DEFAULT_EXTENSION_LABELS,
});

export interface ToolbarProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ExtensionLabels>;
}

export const ToolbarProvider = ({
  children,
  editor = null,
  labels,
}: ToolbarProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_EXTENSION_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <ToolbarContext.Provider value={value}>{children}</ToolbarContext.Provider>
  );
};

export const useToolbar = (): ToolbarContextValue => useContext(ToolbarContext);

export const useToolbarEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(ToolbarContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
    !editor.isDestroyed &&
    editor.extensionManager.extensions.some(
      (extension) => extension.name === name
    )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import type { Editor } from "@tiptap/core";
import { useCallback, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

const isPlainEmpty = <T>(value: T | undefined): value is undefined =>
  value === undefined;

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);
  selectorRef.current = selector;
  isEqualRef.current = isEqual;

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const computeSnapshot = useCallback((): T | undefined => {
    if (!editor) {
      return undefined;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (isPlainEmpty(current) || !isEqualRef.current(current, next)) {
      snapshotRef.current.value = next;
    }
    return snapshotRef.current.value;
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {
          /* Nothing to subscribe to. */
        };
      }
      const update = () => {
        computeSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, computeSnapshot]
  );

  return useSyncExternalStore(subscribe, computeSnapshot, computeSnapshot);
};

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columnActions: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  rowActions: string;
  rows: string;
  splitCell: string;
  tableActions: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Insert Left",
  addColumnRight: "Insert Right",
  addRowAbove: "Insert Above",
  addRowBelow: "Insert Below",
  columnActions: "Column actions",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  rowActions: "Row actions",
  rows: "Rows",
  splitCell: "Split cell",
  tableActions: "Table actions",
};

import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

"use client";

import type { Editor } from "@tiptap/core";
import { Sparkles } from "lucide-react";
import { useCallback, useState } from "react";

import { useToolbarEditor } from "../core/context";
import { useEditorState } from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Popover } from "../ui/popover";
import { PopoverContent } from "../ui/popover-content";
import { generateAiText } from "./client";

export interface AiLabels {
  /** Tooltip / aria-label for the toolbar button. */
  title: string;
  /** Placeholder of the prompt input. */
  placeholder: string;
  /** Label of the submit button. */
  submit: string;
  /** Hint shown when no API key was provided. */
  missingKey: string;
}

export const DEFAULT_AI_LABELS: AiLabels = {
  missingKey: "Add your OpenAI API key to use AI.",
  placeholder: "Ask AI anything…",
  submit: "Generate",
  title: "Ask AI",
};

export interface AiToolbarProps extends ToolbarComponentProps {
  /** OpenAI API key (BYOK). */
  apiKey?: string;
  /** OpenAI model id. Defaults to `gpt-4o-mini`. */
  model?: string;
  /**
   * Optional proxy endpoint (e.g. `/api/ai`). Required for OpenAI, whose API
   * sends no CORS headers and rejects direct browser calls.
   */
  endpoint?: string;
  labels?: Partial<AiLabels>;
}

export const AiToolbar = ({
  className,
  editor: editorProp,
  apiKey,
  model,
  endpoint,
  labels: labelOverrides,
}: AiToolbarProps) => {
  const editor = useToolbarEditor(editorProp);
  const [open, setOpen] = useState(false);
  const [prompt, setPrompt] = useState("");
  const [pending, setPending] = useState(false);
  const [requestError, setRequestError] = useState<string | null>(null);

  const text: AiLabels = { ...DEFAULT_AI_LABELS, ...labelOverrides };

  const disabled =
    useEditorState(
      editor,
      (edit) => edit.isDestroyed || !apiKey,
      (a, b) => a === b
    ) ?? true;

  const insertResult = useCallback(
    (edit: Editor, result: string) => {
      const { from, to } = edit.state.selection;
      if (from === to) {
        edit.chain().focus().insertContentAt(from, result).run();
      } else {
        edit.chain().focus().deleteRange({ from, to }).insertContentAt(from, result).run();
      }
    },
    []
  );

  const onSubmit = useCallback(async () => {
    if (!editor || editor.isDestroyed || !apiKey || prompt.trim() === "" || pending) {
      return;
    }
    setPending(true);
    setRequestError(null);
    try {
      const { from, to } = editor.state.selection;
      const context =
        from === to ? undefined : editor.state.doc.textBetween(from, to, " ");
      const result = await generateAiText({
        apiKey,
        context,
        endpoint,
        model,
        prompt: prompt.trim(),
      });
      insertResult(editor, result);
      setPrompt("");
      setOpen(false);
    } catch (error) {
      setRequestError(error instanceof Error ? error.message : "AI request failed.");
    } finally {
      setPending(false);
    }
  }, [apiKey, editor, endpoint, insertResult, model, pending, prompt]);

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      side="bottom"
      align="start"
      sideOffset={6}
      trigger={
        <Button
          aria-label={apiKey ? text.title : text.missingKey}
          className={["ext-btn--icon-sm", className].filter(Boolean).join(" ")}
          disabled={disabled}
          title={apiKey ? text.title : text.missingKey}
        >
          <Sparkles />
        </Button>
      }
    >
      <PopoverContent className="ext-ai-popover">
        <form
          className="ext-ai-form"
          onSubmit={(e) => {
            e.preventDefault();
            void onSubmit();
          }}
        >
          <Input
            autoFocus
            className="ext-ai-input"
            disabled={pending}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder={text.placeholder}
            value={prompt}
          />
          <Button
            className="ext-ai-submit"
            disabled={pending || prompt.trim() === ""}
            type="submit"
          >
            {pending ? "…" : text.submit}
          </Button>
        </form>
        {requestError ? <p className="ext-ai-error">{requestError}</p> : null}
      </PopoverContent>
    </Popover>
  );
};

import * as React from "react";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  active?: boolean;
  danger?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className = "",
      active = false,
      danger = false,
      type = "button",
      ...props
    },
    ref
  ) => {
    const cls = [
      "ext-btn",
      active ? "ext-btn--active" : "",
      danger ? "ext-btn--danger" : "",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <button
        ref={ref}
        type={type}
        className={cls}
        data-state={active ? "on" : "off"}
        aria-pressed={active}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button };

import * as React from "react";

export type InputProps = React.InputHTMLAttributes<HTMLInputElement>;

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className = "", ...props }, ref) => (
    <input ref={ref} className={`ext-input ${className}`.trim()} {...props} />
  )
);
Input.displayName = "Input";

export { Input };

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode, ReactPortal } from "react";
import { createPortal } from "react-dom";

export type FloatingSide = "bottom" | "top" | "left" | "right";
export type FloatingAlign = "start" | "center" | "end";

export interface UseFloatingOptions {
  align?: FloatingAlign;
  onOpenChange?: (open: boolean) => void;
  open: boolean;
  side?: FloatingSide;
  sideOffset?: number;
}

const clamp = (value: number, max: number): number =>
  Math.max(8, Math.min(value, Math.max(8, max)));

export const useFloating = ({
  align = "center",
  onOpenChange,
  open,
  side = "bottom",
  sideOffset = 4,
}: UseFloatingOptions) => {
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => {
    onOpenChange?.(false);
  }, [onOpenChange]);

  const applyPosition = useCallback(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;
    if (!(trigger instanceof HTMLElement) || !content) {
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const width = content.offsetWidth;
    const height = content.offsetHeight;

    let left: number | undefined;
    let top: number | undefined;
    let right: number | undefined;
    let bottom: number | undefined;
    const translate: string[] = [];

    if (side === "bottom" || side === "top") {
      if (side === "bottom") {
        top = clamp(rect.bottom + sideOffset, window.innerHeight - height);
      } else {
        bottom = window.innerHeight - rect.top + sideOffset;
      }
      if (align === "center") {
        left = clamp(rect.left + rect.width / 2, window.innerWidth - width);
        translate.push("translateX(-50%)");
      } else if (align === "end") {
        right = clamp(
          window.innerWidth - rect.right,
          window.innerWidth - width
        );
      } else {
        left = clamp(rect.left, window.innerWidth - width);
      }
    } else {
      if (side === "right") {
        left = clamp(rect.right + sideOffset, window.innerWidth - width);
      } else {
        right = window.innerWidth - rect.left + sideOffset;
      }
      if (align === "center") {
        top = clamp(rect.top + rect.height / 2, window.innerHeight - height);
        translate.push("translateY(-50%)");
      } else if (align === "end") {
        bottom = window.innerHeight - rect.bottom;
      } else {
        top = clamp(rect.top, window.innerHeight - height);
      }
    }

    content.style.left = left === undefined ? "" : `${left}px`;
    content.style.top = top === undefined ? "" : `${top}px`;
    content.style.right = right === undefined ? "" : `${right}px`;
    content.style.bottom = bottom === undefined ? "" : `${bottom}px`;
    content.style.transform = translate.join(" ");
  }, [align, side, sideOffset]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    applyPosition();
    const handleScroll = () => {
      applyPosition();
    };
    const handleResize = () => {
      applyPosition();
    };
    window.addEventListener("scroll", handleScroll, true);
    window.addEventListener("resize", handleResize);
    return () => {
      window.removeEventListener("scroll", handleScroll, true);
      window.removeEventListener("resize", handleResize);
    };
  }, [applyPosition, open]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const handlePointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (triggerRef.current?.contains(target) ||
          contentRef.current?.contains(target))
      ) {
        return;
      }
      close();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [close, open]);

  const content = (children: ReactNode): null | ReactPortal =>
    open
      ? createPortal(
          <div
            ref={contentRef}
            data-ext-floating
            style={{ position: "fixed", zIndex: 60 } as CSSProperties}
          >
            {children}
          </div>,
          document.body
        )
      : null;

  return { content, triggerRef };
};

import * as React from "react";
import { useCallback } from "react";

import { useFloating } from "./use-floating";
import type { FloatingAlign, FloatingSide } from "./use-floating";

export type PopoverAlign = FloatingAlign;
export type PopoverSide = FloatingSide;

export interface PopoverProps {
  align?: PopoverAlign;
  children: React.ReactNode;
  className?: string;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  side?: PopoverSide;
  sideOffset?: number;
  trigger: React.ReactElement;
}

const Popover = ({
  align = "center",
  children,
  onOpenChange,
  open = false,
  side = "bottom",
  sideOffset = 4,
  trigger,
}: PopoverProps) => {
  const { content, triggerRef } = useFloating({
    align,
    onOpenChange,
    open,
    side,
    sideOffset,
  });

  const toggle = useCallback(() => {
    onOpenChange?.(!open);
  }, [onOpenChange, open]);

  const triggerWithHandlers = React.cloneElement(
    trigger as React.ReactElement<
      React.HTMLAttributes<HTMLElement> & { ref?: React.Ref<HTMLElement> }
    >,
    {
      "aria-expanded": open,
      "aria-haspopup": "dialog",
      onClick: toggle,
      ref: triggerRef,
    }
  );

  return (
    <>
      {triggerWithHandlers}
      {content(children)}
    </>
  );
};

Popover.displayName = "Popover";

export { Popover };

import * as React from "react";
import { useCallback, useState } from "react";

export interface DropdownPillHandlers {
  onFocus: (event: React.FocusEvent<HTMLDivElement>) => void;
  onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => void;
  onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => void;
}

interface PillRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

const useDropdownPill = (
  onMouseLeave?: (event: React.MouseEvent<HTMLDivElement>) => void
): { handlers: DropdownPillHandlers; pill: React.ReactNode } => {
  const [rect, setRect] = useState<PillRect | null>(null);

  const handleItemEnter = useCallback((target: EventTarget | null) => {
    const item = (target as HTMLElement).closest<HTMLElement>(
      "[data-dropdown-item]"
    );
    if (!item) {
      return;
    }
    setRect({
      height: item.offsetHeight,
      left: item.offsetLeft,
      top: item.offsetTop,
      width: item.offsetWidth,
    });
  }, []);

  const handlers: DropdownPillHandlers = {
    onFocus: (event: React.FocusEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
    onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => {
      setRect(null);
      onMouseLeave?.(event);
    },
    onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
  };

  const pill = (
    <div
      aria-hidden="true"
      className={["ext-dropdown-pill", rect ? "ext-dropdown-pill--visible" : ""]
        .filter(Boolean)
        .join(" ")}
      style={
        rect
          ? {
              height: rect.height,
              left: rect.left,
              top: rect.top,
              width: rect.width,
            }
          : undefined
      }
    />
  );

  return { handlers, pill };
};

export { useDropdownPill };

import * as React from "react";

import { useDropdownPill } from "./dropdown-pill";

export type PopoverContentProps = React.HTMLAttributes<HTMLDivElement>;

const PopoverContent = React.forwardRef<HTMLDivElement, PopoverContentProps>(
  ({ className = "", onMouseLeave, ...props }, ref) => {
    const { handlers, pill } = useDropdownPill(onMouseLeave);

    return (
      <div
        ref={ref}
        className={`ext-popover-content ${className}`.trim()}
        {...handlers}
        {...props}
      >
        {pill}
        {props.children}
      </div>
    );
  }
);
PopoverContent.displayName = "PopoverContent";

export { PopoverContent };

/* AI assistant styles using shadcn CSS variables. */

.ext-ai-popover {
  width: 20rem;
  max-width: calc(100vw - 2rem);
}

.ext-ai-form {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.ext-ai-input {
  flex: 1;
  min-width: 0;
}

.ext-ai-submit {
  flex-shrink: 0;
}

.ext-ai-error {
  margin: 0.5rem 0 0;
  font-size: 0.75rem;
  line-height: 1.4;
  color: var(--destructive);
}

/* Extensions UI primitives using shadcn CSS variables */

@keyframes ext-pop-in {
  from {
    opacity: 0;
    translate: 0 0.25rem;
    scale: 0.95;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* ── Button ── */
.ext-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: inherit;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    border-color 150ms ease-out,
    transform 100ms ease-out;
}

.ext-btn > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-btn--icon {
  width: 2rem;
  padding: 0;
}

.ext-btn--icon-sm {
  width: 1.75rem;
  padding: 0;
}

.ext-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.ext-btn:active {
  transform: scale(0.96);
}

.ext-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-btn--active {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn--danger {
  color: var(--destructive, #ef4444);
}

.ext-btn--danger:hover {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

/* ── Dropdown ── */
.ext-dropdown-content {
  position: relative;
  min-width: 10rem;
  padding: 0.25rem;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-item {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.375rem 0.5rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-dropdown-item > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.ext-dropdown-pill--visible {
  opacity: 1;
}

.ext-dropdown-item:hover,
.ext-dropdown-item:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-dropdown-item:active {
  transform: scale(0.98);
}

.ext-dropdown-item:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-dropdown-item--danger {
  color: var(--destructive, #ef4444);
}

.ext-dropdown-item--danger:hover,
.ext-dropdown-item--danger:focus-visible {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

.ext-dropdown-separator {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

/* ── Popover ── */
.ext-popover-content {
  position: relative;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ── Separator ── */
.ext-separator {
  flex-shrink: 0;
  background: var(--border);
}

.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
